CREATE TYPE "DocumentAnalysisStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED');
CREATE TABLE "DocumentAnalysis" ("id" UUID NOT NULL DEFAULT uuid_generate_v4(), "documentId" UUID NOT NULL, "status" "DocumentAnalysisStatus" NOT NULL DEFAULT 'QUEUED', "summary" JSONB, "topicsJson" JSONB, "provider" TEXT, "model" TEXT, "promptVersion" TEXT NOT NULL DEFAULT 'm2b-2a-v1', "errorCode" TEXT, "errorMessage" TEXT, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DocumentAnalysis_pkey" PRIMARY KEY ("id"), CONSTRAINT "DocumentAnalysis_documentId_key" UNIQUE ("documentId"), CONSTRAINT "DocumentAnalysis_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "Document"("id") ON DELETE CASCADE);
